package com.aoo.bcg.common.metrics;
import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;
class DynamicMetricRegistryTest{@Test void dynamicRoomAndPlayMetersUnregisterWithoutGrowth(){var registry=new DynamicMetricRegistry(4);for(int index=0;index<1000;index++){try(var room=registry.register("room.active",Map.of("gameId","10","playVersion","v2"));var play=registry.register("play.operation",Map.of("gameId","10","action","play"))){assertEquals(2,registry.seriesCount());}}assertEquals(0,registry.seriesCount());}@Test void rejectsHighCardinalityTagsAndSeriesOverflow(){var registry=new DynamicMetricRegistry(1);assertThrows(IllegalArgumentException.class,()->registry.register("room.active",Map.of("roomId","7")));var first=registry.register("room.active",Map.of("gameId","10"));assertThrows(IllegalStateException.class,()->registry.register("room.active",Map.of("gameId","11")));first.close();assertEquals(0,registry.seriesCount());}}
